const node = this.buildNode(context, target);
/* DSHA_CONVERSATION_MATERIALIZED_WITHDRAWAL_V1: A definition may temporarily lose its source while a paged window or projection settles. Keep the stable node key with hidden visibility so one transient withdrawal cannot abort the event-feed subscriber. */
const retained = node === null && previous !== null
	? (previous.visibility === "hidden" ? previous : { ...previous, visibility: "hidden" })
	: node;
context.current.set(target, retained);
if (retained !== null) upserts.push(retained);
